// Generated by tests/tools/designer-sim.js from tests/sim/fixture.json. DO NOT EDIT.
//
// One line per widget: the name, its generated struct field, and the rectangle the canvas placed it
// at. The simulator compares each against what the layout engine reports.

pub const CANVAS_W: u32 = 480;
pub const CANVAS_H: u32 = 320;

/// Where to look for paint, and what colour the widget under it was filled with.
pub const EXPECTED_FILL: (i32, i32, Rgb565) = (21, 62, Rgb565::new(7, 27, 20));

/// The probed widget's own rectangle, so a failure can show what was painted inside it.
pub const PROBE_RECT: (i32, i32, u32, u32) = (17, 48, 43, 29);

/// The widget the design gives a font to: what the two renders must disagree about.
pub const FONTED_RECT: (i32, i32, u32, u32) = (200, 120, 90, 30);

/// A point just outside the probed widget, to compare paint against.
pub const PROBE_REFERENCE: (i32, i32) = (13, 62);

/// Every widget, against the engine's own answer for where it ended up.
pub fn check(
    rect_of: &dyn Fn(WidgetId) -> Option<Rect>,
    widgets: &crate::screen::SimPanelWidgets,
) -> Vec<String> {
    let mut problems: Vec<String> = Vec::new();
    let mut one = |name: &str, id: WidgetId, x: i32, y: i32, w: u32, h: u32| {
        match rect_of(id) {
            None => problems.push(format!("{name}: the engine has no rect for this widget")),
            Some(rect) => {
                if rect.x != x || rect.y != y || rect.w != w || rect.h != h {
                    problems.push(format!(
                        "{name}: the canvas placed it at ({x}, {y}) {w}x{h}, the engine laid it out at ({}, {}) {}x{}",
                        rect.x, rect.y, rect.w, rect.h
                    ));
                }
            }
        }
    };
    // "tiny" (spacer) has no generated field: the parser drops its id.
    one("band", widgets.band, 0, 0, 480, 40);
    one("title", widgets.title, 17, 3, 200, 24);
    one("go", widgets.go, 17, 48, 43, 29);
    one("knob", widgets.knob, 100, 60, 40, 30);
    one("meter", widgets.meter, 0, 280, 480, 20);
    one("foot", widgets.foot, 0, 300, 240, 20);
    one("foot2", widgets.foot2, 240, 300, 240, 20);
    one("eco", widgets.eco, 60, 120, 40, 30);
    one("ok", widgets.ok, 300, 120, 60, 30);
    one("fonted", widgets.fonted, 200, 120, 90, 30);
    one("builtin", widgets.builtin, 200, 160, 90, 30);
    one("builtinButton", widgets.builtin_button, 300, 160, 90, 30);
    one("styled", widgets.styled, 200, 200, 90, 30);
    one("grid", widgets.grid, 0, 234, 200, 44);
    one("tinted", widgets.tinted, 300, 200, 90, 30);
    one("check", widgets.check, 0, 155, 150, 26);
    one("spin", widgets.spin, 0, 185, 150, 26);
    one("roll", widgets.roll, 0, 215, 150, 18);
    one("gauge", widgets.gauge, 390, 120, 90, 90);
    one("sld", widgets.sld, 150, 120, 50, 18);
    one("arc", widgets.arc, 150, 140, 50, 38);
    one("whl", widgets.whl, 150, 180, 24, 24);
    one("ind", widgets.ind, 150, 206, 40, 12);
    one("crm", widgets.crm, 150, 220, 40, 12);
    one("cht", widgets.cht, 200, 236, 46, 36);
    one("plt", widgets.plt, 248, 236, 46, 36);
    one("pth", widgets.pth, 440, 212, 40, 40);
    one("stb", widgets.stb, 390, 266, 90, 13);
    one("tme", widgets.tme, 390, 212, 45, 26);
    one("num", widgets.num, 390, 240, 45, 22);
    one("trib", widgets.trib, 300, 260, 40, 40);
    one("rule", widgets.rule, 300, 305, 80, 4);
    problems
}

/// Taps the centre of every widget that raises an event, and checks what comes back.
pub fn touch_checks<const N: usize, const E: usize, const D: usize>(
    gui: &mut GuiContext<'_, N, E, D>,
    widgets: &crate::screen::SimPanelWidgets,
) -> Vec<String> {
    /// A press and a release at one point, with the timing the crate needs to call it a click.
    fn tap<const N: usize, const E: usize, const D: usize>(
        gui: &mut GuiContext<'_, N, E, D>,
        x: i32,
        y: i32,
    ) -> Vec<UiEvent> {
        let _ = gui.handle_input(InputEvent::Pointer {
            x,
            y,
            state: PointerState::Pressed,
            button: PointerButton::Primary,
        });
        let _ = gui.tick_input(20);
        let _ = gui.handle_input(InputEvent::Pointer {
            x,
            y,
            state: PointerState::Released,
            button: PointerButton::Primary,
        });
        let _ = gui.tick_input(20);
        let mut events = Vec::new();
        while let Some(event) = gui.pop_event() {
            events.push(event);
        }
        events
    }

    let mut problems: Vec<String> = Vec::new();
    {
        let events = tap(gui, 38, 62);
        let raised = events.iter().any(|event| matches!(event, UiEvent::Clicked(other) | UiEvent::ValueChanged(other) if *other == widgets.go));
        if !raised {
            problems.push(format!("go: a tap at its designed centre (38, 62) raised nothing for it ({} events came back)", events.len()));
        }
    }
    {
        let events = tap(gui, 80, 135);
        let raised = events.iter().any(|event| matches!(event, UiEvent::Clicked(other) | UiEvent::ValueChanged(other) if *other == widgets.eco));
        if !raised {
            problems.push(format!("eco: a tap at its designed centre (80, 135) raised nothing for it ({} events came back)", events.len()));
        }
    }
    {
        let events = tap(gui, 330, 135);
        let raised = events.iter().any(|event| matches!(event, UiEvent::Clicked(other) | UiEvent::ValueChanged(other) if *other == widgets.ok));
        if !raised {
            problems.push(format!("ok: a tap at its designed centre (330, 135) raised nothing for it ({} events came back)", events.len()));
        }
    }
    {
        let events = tap(gui, 345, 175);
        let raised = events.iter().any(|event| matches!(event, UiEvent::Clicked(other) | UiEvent::ValueChanged(other) if *other == widgets.builtin_button));
        if !raised {
            problems.push(format!("builtinButton: a tap at its designed centre (345, 175) raised nothing for it ({} events came back)", events.len()));
        }
    }
    {
        // Nothing is under this point, so nothing may claim it.
        let events = tap(gui, 360, 250);
        let claimed = events
            .iter()
            .filter(|event| matches!(event, UiEvent::Clicked(_) | UiEvent::ValueChanged(_)))
            .count();
        if claimed != 0 {
            problems.push(format!("a tap at (360, 250), where no widget is, was claimed by {} widget event(s)", claimed));
        }
    }
    problems
}
